namespace HelpingHands.Api.Data;

// Identifiers are generated by the API, not supplied by callers.
public sealed class Referral
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string Reference { get; set; } = "";
    public Guid RequestId { get; set; }
    public Guid? NeedId { get; set; }
    public Guid RecipientId { get; set; }
    public decimal AssignedQuantity { get; set; }
    public string ScopeDescription { get; set; } = "";
    public string Status { get; set; } = "Assigned";
    public Guid CreatedByUserId { get; set; }
    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
    public Guid Version { get; set; } = Guid.NewGuid();
}

public sealed class Outcome
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string Reference { get; set; } = "";
    public Guid ReferralId { get; set; }
    public Guid ReportedByUserId { get; set; }
    public decimal ReportedQuantity { get; set; }
    public string Description { get; set; } = "";
    public string Status { get; set; } = "Draft";
    public DateTimeOffset? SubmittedAt { get; set; }
    public Guid Version { get; set; } = Guid.NewGuid();
}

public sealed class OutcomeReview
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid OutcomeId { get; set; }
    public Guid ActorUserId { get; set; }
    public string Decision { get; set; } = "";
    public string? Reason { get; set; }
    public DateTimeOffset ReviewedAt { get; set; } = DateTimeOffset.UtcNow;
}

public sealed class EvidenceAttachment
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid OutcomeId { get; set; }
    public string StorageKey { get; set; } = "";
    public string OriginalName { get; set; } = "";
    public string MediaType { get; set; } = "";
    public long SizeBytes { get; set; }
    public Guid UploadedByUserId { get; set; }
    public DateTimeOffset UploadedAt { get; set; } = DateTimeOffset.UtcNow;
}
